import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });
const now = () => new Date().toISOString();
const heartbeat = () => db.prepare('INSERT INTO worker_health (id, heartbeat) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET heartbeat = excluded.heartbeat').run(Date.now());
// Replay interrupted work within its existing attempt, without exhausting retries on crashes.
db.prepare(\"UPDATE jobs SET status = 'queued', completed = 0, recovering = 1, availableAt = 0, updatedAt = ? WHERE status = 'running'\").run(now());
heartbeat();
const timer = setInterval(heartbeat, 500);
