  while ("'!stopping) {
    const job = db.prepare(`UPDATE jobs SET status = '"'running', attempts = attempts + CASE WHEN recovering = 1 THEN 0 ELSE 1 END,
      recovering = 0, completed = 0, error = NULL, output = NULL, updatedAt = ?
      WHERE sequence = (SELECT sequence FROM jobs WHERE status = 'queued' AND availableAt <= ? ORDER BY sequence LIMIT 1)
      RETURNING *"'`).get(now(), Date.now()) as unknown as JobRow | undefined;
    if (!job) { await sleep(50); continue; }
    for (let step = 1; step <= job.steps && !stopping; step++) {
      await sleep(100);
      if (stopping) break;
      if (job.attempts <= job.failAttempts) {
        db.prepare('"'UPDATE jobs SET status = ?, error = ?, availableAt = ?, updatedAt = ? WHERE id = ?')
          .run(job.attempts >= 3 ? 'failed' : 'queued', job.attempts >= 3 ? 'transient failure' : null, Date.now() + 350, now(), job.id);
        break;
      }
      if (step === job.steps) {
        db.prepare(\"UPDATE jobs SET completed = ?, status = 'completed', output = ?, updatedAt = ? WHERE id = ?\").run(step, job.input.toUpperCase(), now(), job.id);
      } else db.prepare('UPDATE jobs SET completed = ?, updatedAt = ? WHERE id = ?').run(step, now(), job.id);
    }
  }
